import os
import azure.cognitiveservices.speech as speechsdk
from google.cloud import speech_v1p1beta1 as speech_google
import boto3
from ibm_watson import SpeechToTextV1
from ibm_cloud_sdk_core.authenticators import IAMAuthenticator

def get_azure_speech_recognizer():
    speech_config = speechsdk.SpeechConfig(
        subscription=os.environ.get("SPEECH_KEY"), 
        region=os.environ.get("SPEECH_REGION")
    )
    audio_config = speechsdk.AudioConfig(use_microphone=True)
    return speechsdk.SpeechRecognizer(
        speech_config=speech_config, 
        audio_config=audio_config
    )

def get_google_speech_client():
    return speech_google.SpeechClient()

def get_aws_transcribe_client():
    return boto3.client(
        "transcribe",
        region_name=os.environ.get("AWS_REGION"),
        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY")
    )

def get_watson_speech_to_text_client():
    authenticator = IAMAuthenticator(os.environ.get("WATSON_SPEECH_TO_TEXT_APIKEY"))
    speech_to_text = SpeechToTextV1(
        authenticator=authenticator
    )
    speech_to_text.set_service_url(os.environ.get("WATSON_SPEECH_TO_TEXT_URL"))
    return speech_to_text

import dataclasses
from typing import Optional, List

@dataclasses.dataclass
class TranscriptionResult:
    text: str
    is_partial: bool
    language: Optional[str] = None
    confidence: Optional[float] = None

@dataclasses.dataclass
class AudioChunk:
    data: bytes
    sequence_number: int

def normalize_azure_result(event) -> TranscriptionResult:
    return TranscriptionResult(
        text=event.result.text,
        is_partial=(event.result.reason == speechsdk.ResultReason.RecognizingSpeech),
        confidence=event.result.confidence if hasattr(event.result, 'confidence') else None # Azure SDK might not directly expose confidence on all events
    )

def normalize_google_result(streaming_recognize_response) -> Optional[TranscriptionResult]:
    if not streaming_recognize_response.results:
        return None
    result = streaming_recognize_response.results[0]
    return TranscriptionResult(
        text=result.alternatives[0].transcript,
        is_partial=not result.is_final,
        confidence=result.alternatives[0].confidence
    )

def normalize_aws_result(aws_transcript_event) -> List[TranscriptionResult]:
    results = []
    for result in aws_transcript_event["Results"]:
        if "Alternatives" in result and result["Alternatives"]:
            results.append(TranscriptionResult(
                text=result["Alternatives"][0]["Transcript"],
                is_partial=result["IsPartial"],
                confidence=result["Alternatives"][0].get("Confidence")
            ))
    return results

def normalize_watson_result(watson_data) -> List[TranscriptionResult]:
    results = []
    if "results" in watson_data:
        for result in watson_data["results"]:
            if "alternatives" in result and result["alternatives"]:
                results.append(TranscriptionResult(
                    text=result["alternatives"][0]["transcript"],
                    is_partial=not result["final"],
                    confidence=result["alternatives"][0].get("confidence")
                ))
    return results

import os
from openai import OpenAI

openai_client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

def check_safety(text: str) -> dict:
    try:
        response = openai_client.moderations.create(input=text)
        moderation_result = response.results[0]
        return {
            "flagged": moderation_result.flagged,
            "categories": moderation_result.categories.model_dump(),
            "category_scores": moderation_result.category_scores.model_dump()
        }
    except Exception as e:
        return {"error": str(e)}

if __name__ == "__main__":
    # Example usage
    text_to_check_safe = "This is a perfectly safe statement."
    safe_result = check_safety(text_to_check_safe)
    print(f"Safety check for \"{text_to_check_safe}\": {safe_result}")

    text_to_check_unsafe = "I want to kill myself."
    unsafe_result = check_safety(text_to_check_unsafe)
    print(f"Safety check for \"{text_to_check_unsafe}\": {unsafe_result}")
